def encode(message):
    vowels = 'aeiou'
    shifted_vowels = {v: chr((ord(v) - ord('a') + 2) % 26 + ord('a')) for v in vowels}
    shifted_vowels.update({v.upper(): shifted_vowels[v].upper() for v in vowels})

    encoded_message = []
    for char in message:
        if char.isalpha():
            if char.islower():
                encoded_message.append(shifted_vowels.get(char, char).upper())
            else:
                encoded_message.append(shifted_vowels.get(char, char).lower())
        else:
            encoded_message.append(char)

    return ''.join(encoded_message)

