import heapq

def minPath(grid, k):
    N = len(grid)
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    pq = [(grid[0][0], 0, 0, [grid[0][0]])]
    visited = set()

    while pq:
        val, x, y, path = heapq.heappop(pq)
        if (x, y) in visited or len(path) > k:
            continue
        visited.add((x, y))
        if len(path) == k:
            return path
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < N and 0 <= ny < N:
                heapq.heappush(pq, (val + grid[nx][ny], nx, ny, path + [grid[nx][ny]]))
    return []

